<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes;
class LanguageStudent extends Model { use SoftDeletes; protected $guarded=[]; protected $casts=['date_of_birth'=>'date','registered_at'=>'date','official_enrollment_date'=>'date']; protected static function booted():void{static::creating(function(self $student){if(blank($student->code))$student->code=\App\Support\CenterCode::next('language_students','HV');});} public function guardians(){return $this->hasMany(LanguageGuardian::class);} public function enrollments(){return $this->hasMany(LanguageEnrollment::class);} public function tuitionCharges(){return $this->hasMany(LanguageTuitionCharge::class,'language_student_id');} public function course(){return $this->belongsTo(LanguageCourse::class,'language_course_id')->withTrashed();} public function discountPolicy(){return $this->belongsTo(LanguageDiscountPolicy::class,'language_discount_policy_id')->withTrashed();} }
